# claude-deck tab titles: "● 2 JobScraper 4m", colored by the most urgent
# session in the tab. Used through tab_title_template "{custom}".
# Generated by claude-deck; edits are overwritten when the deck starts.
import json
import os
import time

_STATE = os.path.join(os.environ.get('XDG_RUNTIME_DIR') or f'/tmp/claude-deck-{os.getuid()}', 'claude-deck', 'state.json')
_cache = {'mtime': -1.0, 'data': {}}

COLORS = {
    'working': '5fbf7a',
    'needs_you': 'f5a524',
    'your_turn': 'ff5a6a',
    'your_turn_seen': 'a8505a',
    'exited': '7a6a6c',
}
# Lower is more urgent; the tab shows its most urgent session.
RANK = {'needs_you': 0, 'your_turn': 1, 'working': 2, 'your_turn_seen': 3, 'exited': 4}
GLYPH = {'working': '●', 'needs_you': '◆', 'your_turn': '●', 'your_turn_seen': '○', 'exited': '◌'}


def _state() -> dict:
    try:
        mtime = os.stat(_STATE).st_mtime
    except OSError:
        return {}
    if mtime != _cache['mtime']:
        try:
            with open(_STATE) as f:
                _cache['data'] = json.load(f)
            _cache['mtime'] = mtime
        except (OSError, ValueError):
            pass
    return _cache['data']


def _key(s: dict) -> str:
    status = s.get('status')
    if status == 'your_turn' and s.get('seen'):
        return 'your_turn_seen'
    # A status this file doesn't know (a newer daemon) must not break the title.
    return status if status in COLORS else 'exited'


def _elapsed(ms: int) -> str:
    secs = max(0, int(time.time() - ms / 1000))
    if secs < 60:
        return ''
    if secs < 3600:
        return f' {secs // 60}m'
    return f' {secs // 3600}h{(secs % 3600) // 60:02d}'


def draw_title(data: dict) -> str:
    from kitty.boss import get_boss
    fmt = data['fmt']
    title = data.get('title', '')
    tab = get_boss().tab_for_id(data.get('tab_id', -1))
    windows = _state().get('windows', {})
    sessions = []
    if tab is not None:
        for w in tab:
            s = windows.get(str(w.id))
            if s:
                sessions.append(s)
    if not sessions:
        return f'{data["index"]} {title}'
    sessions.sort(key=lambda s: RANK.get(_key(s), 9))
    top = sessions[0]
    key = _key(top)
    color = getattr(fmt.fg, '_' + COLORS[key])
    if len(sessions) <= 4:
        dots = ''.join(getattr(fmt.fg, '_' + COLORS[_key(s)]) + GLYPH[_key(s)] for s in sessions)
    else:
        # A crowded tab: one dot and a count per state, most urgent first.
        counts = {}
        for s in sessions:
            counts[_key(s)] = counts.get(_key(s), 0) + 1
        dots = ' '.join(getattr(fmt.fg, '_' + COLORS[k]) + GLYPH[k] + str(n)
                        for k, n in sorted(counts.items(), key=lambda kv: RANK.get(kv[0], 9)))
    name = top.get('project', title)
    if len(sessions) > 1:
        name += f' +{len(sessions) - 1}'
    # The model, when it means something for the whole tab: one session, or all alike.
    models = {s.get('model') for s in sessions}
    model = next(iter(models)) if len(models) == 1 else None
    model_part = f'{fmt.fg._9a8a8c} · {model}{fmt.fg.tab}' if model else ''
    timer = _elapsed(top.get('since', 0)) if key in ('needs_you', 'your_turn') else ''
    return f'{dots}{fmt.fg.tab} {top.get("index", data["index"])} {name}{model_part}{color}{timer}{fmt.fg.tab}'
